update public.content_variants set body = $json${"text":"Doni borrowed IDR 2 million from the pinjol application to buy crypto which was going viral. He feels this is an investment, even though he doesn't understand the project and has to pay interest on the loan. This is high-risk speculation."}$json$::jsonb, body_id = $json${"text":"Doni meminjam Rp 2 juta dari aplikasi pinjol untuk membeli kripto yang sedang viral. Ia merasa ini investasi, padahal ia tidak mengerti proyeknya dan harus membayar bunga pinjol. Ini adalah spekulasi berisiko tinggi."}$json$::jsonb where id = '00cd4e2b-9498-43c8-9b58-50008dd98f38';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"45 most liquid stocks on IDX","options":["50 smallest stocks on IDX","45 most liquid stocks on IDX","100 property shares","All shares on IDX"],"question":"The LQ45 (XISX) ETF tracks...","difficulty":"beginner","explanation":"LQ45 is an index consisting of 45 shares with the highest liquidity and market capitalization on the Indonesian Stock Exchange."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"45 saham paling likuid di IDX","options":["50 saham terkecil di IDX","45 saham paling likuid di IDX","100 saham properti","Semua saham di IDX"],"question":"ETF LQ45 (XISX) melacak...","difficulty":"beginner","explanation":"LQ45 adalah indeks yang terdiri dari 45 saham dengan likuiditas dan kapitalisasi pasar tertinggi di Bursa Efek Indonesia."}$json$::jsonb where id = '05a4616d-83bc-4f68-9069-707c5d3ac58d';
update public.content_variants set body = $json${"type":"fill_blank","answer":"avalanche","question":"The _____ method targets the debt with the highest interest first.","difficulty":"beginner","explanation":"Avalanche prioritizes paying off high-interest debt to save on total interest costs."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"avalanche","question":"Metode _____ menargetkan utang dengan bunga tertinggi terlebih dahulu.","difficulty":"beginner","explanation":"Avalanche mengutamakan pelunasan utang berbunga tinggi untuk menghemat biaya bunga total."}$json$::jsonb where id = '06badc70-d1fe-4a5f-8cd5-1677f9723c59';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"A digital ledger that is shared across multiple computers","options":["A digital ledger that is shared across multiple computers","Central bank for crypto","Chat application for traders","New coin type"],"question":"What is blockchain in simple terms?","difficulty":"beginner","explanation":"A blockchain is a public ledger spread across thousands of computers, making it difficult to change alone."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Buku besar digital yang dibagikan ke banyak komputer","options":["Buku besar digital yang dibagikan ke banyak komputer","Bank sentral untuk kripto","Aplikasi chatting untuk trader","Jenis koin baru"],"question":"Apa itu blockchain secara sederhana?","difficulty":"beginner","explanation":"Blockchain adalah buku besar publik yang tersebar di ribuan komputer, sehingga sulit diubah sendirian."}$json$::jsonb where id = '06cedb38-a0f4-4342-9612-c92d12fd11b5';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"PayLater has no additional fees as long as you pay on time.","difficulty":"beginner","explanation":"Even though there are often 0% interest promos, some PayLaters still charge administration fees or fines if they are late. Always read the terms."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"PayLater tidak ada biaya tambahan asal bayar tepat waktu.","difficulty":"beginner","explanation":"Meski sering ada promo bunga 0%, beberapa PayLater tetap mengenakan biaya administrasi atau denda jika telat. Selalu baca ketentuan."}$json$::jsonb where id = '0a1a2ebd-0029-4197-8126-58841915c4bb';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Credit cards always charge interest from the day of purchase.","difficulty":"beginner","explanation":"If the bill is paid in full before the due date, the cardholder is usually not charged interest during the grace period."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Kartu kredit selalu mengenakan bunga sejak hari pembelian.","difficulty":"beginner","explanation":"Jika tagihan dibayar penuh sebelum jatuh tempo, pemegang kartu biasanya tidak dikenakan bunga selama masa tenggang."}$json$::jsonb where id = '0ae37ac8-dc5d-4774-a775-bc2397719716';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Motorcycle credit is always a bad debt.","difficulty":"beginner","explanation":"Motorcycle credit can be a good debt if it is used for work and generates income that exceeds the installments."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Kredit motor selalu termasuk utang buruk.","difficulty":"beginner","explanation":"Kredit motor bisa jadi utang baik jika digunakan untuk bekerja dan menghasilkan pendapatan yang melebihi cicilan."}$json$::jsonb where id = '0bad0dbd-4b67-4b8b-9c21-7b42268a4a70';
update public.content_variants set body = $json${"text":"Rina wants to start investing in the Indonesian stock market but is confused about which shares to choose. He chose ETF LQ45 (XISX) which tracks 45 shares of the largest and most liquid companies in Indonesia—BBCA, BBRI, TLKM, ASII, and others. With one purchase, Rina now owns a small portion of 45 of Indonesia's top companies."}$json$::jsonb, body_id = $json${"text":"Rina ingin mulai investasi di pasar saham Indonesia tapi bingung memilih saham mana. Dia memilih ETF LQ45 (XISX) yang melacak 45 saham perusahaan terbesar dan paling likuid di Indonesia—BBCA, BBRI, TLKM, ASII, dan lainnya. Dengan satu pembelian, Rina sekarang memiliki porsi kecil dari 45 perusahaan top Indonesia."}$json$::jsonb where id = '0be04543-dc6b-4d50-9292-d0250db604eb';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"The house or host has a mathematical advantage","options":["The house or host has a mathematical advantage","The results can be predicted with certainty","Have real assets","Guaranteed by the government"],"question":"What are the main characteristics of gambling compared to investment?","difficulty":"beginner","explanation":"Gambling is designed so that the bookie or house wins in the long run, unlike productive assets."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Rumah atau penyelenggara memiliki keunggulan matematis","options":["Rumah atau penyelenggara memiliki keunggulan matematis","Hasilnya bisa diprediksi dengan pasti","Memiliki aset nyata","Dijamin oleh pemerintah"],"question":"Apa ciri utama judi dibandingkan investasi?","difficulty":"beginner","explanation":"Judi dirancang agar bandar atau rumah menang dalam jangka panjang, tidak seperti aset produktif."}$json$::jsonb where id = '10e712f0-fc61-493b-be26-8a1073110247';
update public.content_variants set body = $json${"type":"fill_blank","answer":"Giro","question":"The _____ account is suitable for high volume business transactions and requires a checkbook.","difficulty":"beginner","explanation":"Current Accounts are designed for business transactions with features such as a checkbook and high transaction limits, although the interest is low."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"Giro","question":"Rekening _____ cocok untuk transaksi bisnis dengan volume tinggi dan butuh buku cek.","difficulty":"beginner","explanation":"Rekening Giro (Current Account) dirancang untuk transaksi bisnis dengan fitur seperti buku cek dan batas transaksi tinggi, meski bunganya rendah."}$json$::jsonb where id = '128be0c0-e2d4-4c2e-9874-ada972c9d8c1';

